/*
 * 菜品库：内置菜品的静态数据，所有空间共享同一份。数量看 LIBRARY_DISHES.length，
 * 不在注释里写数字——上一版写着「300 道」时实际已经 302 道了。
 * 用户在 /chufang/library 里搜索后挑选加入自己的菜单（写入 menu_items），
 * 加入后与手动添加的菜完全等价，可自由编辑/换图/归档。
 *
 * cat 是「建议分类」，对应 lib/categories.ts 的预置类目 id；
 * 用户加入时可以改成自己空间里的任意分类。
 * tags 只服务于搜索（别名/主料/做法），不展示给用户。
 *
 * Bundled watercolor covers use 560x560 JPEGs (at most 60 KiB).
 * Lists use separate 120x120 thumbnails to keep bandwidth low.
 * 没有 img 的菜暂时无图，列表和详情都有渐变占位兜底；
 * 管理员在 /admin 配的图（library_images 表）优先级更高。
 */

export interface LibraryDish {
  name: string;
  cat: string;
  tags: string[];
  ingredients: string;
  instructions: string;
  /** Slug under public/library/, e.g. "lib-001". Absent = no illustration yet. */
  img?: string;
  description?: string;
  servings?: string;
  timeMinutes?: number;
}

/* Filter chips on /chufang/library, ordered like PRESET_CATEGORIES.
 * Every id here must exist in lib/categories.ts, and every cat used by a dish
 * below must appear here — a cat that is missing renders a chip with an empty
 * label and its dishes become unreachable through the filter. */
export const LIBRARY_CATS = [
  { id: "zaochan", name: "早餐" },
  { id: "zhushi", name: "米饭" },
  { id: "mianshi", name: "面食" },
  { id: "rourou", name: "肉类" },
  { id: "caicai", name: "菜类" },
  { id: "tangtang", name: "汤羹" },
  { id: "haixian", name: "海鲜" },
  { id: "liangcai", name: "凉菜" },
  { id: "shuiguo", name: "水果" },
  { id: "tianpin", name: "甜点" },
  { id: "yinpin", name: "喝的" },
  { id: "yexiao", name: "夜宵" },
] as const;

const D = (name: string, cat: string, tags: string[], ingredients: string, instructions: string, img?: string, details?: Pick<LibraryDish, "description" | "servings" | "timeMinutes">): LibraryDish =>
  ({ name, cat, tags, ingredients, instructions, img, ...details });

/** Static illustration for a library dish, or null when it has none. */
export function libraryImageUrl(dish: LibraryDish): string | null {
  return dish.img ? '/library/' + dish.img + '.jpg' : null;
}

/**
 * 120x120 版本，给列表里的小缩略图用（public/library/thumb/）。
 *
 * 菜品库列表一屏能出十几行，每行的图只有 52x52，用 560 的原图渲染等于
 * 一个游客翻完 416 行要拉 8.7MB —— 服务器上行只有 4 Mbps，那是 20 秒独占。
 * 缩略图全套加起来 0.58MB，省 15 倍。
 * 加进用户自己菜单时仍然存原图 URL（详情页是整屏宽的），不要在那里用这个。
 */
export function libraryThumbUrl(dish: LibraryDish): string | null {
  return dish.img ? '/library/thumb/' + dish.img + '.jpg' : null;
}

